use crate::AuditError;
const CLAIM: &str = "SYNTHETIC_COMMAND_INTENT_TEST_PLAN_ONLY_NOT_SIGNATURE_VERIFICATION_OR_CYBER_ASSURANCE";
#[derive(Debug,Clone,Copy,PartialEq,Eq)] pub enum IdentityStatus{Current,Unknown,Revoked,Expired}
#[derive(Debug,Clone,Copy,PartialEq,Eq)] pub enum SignatureStatus{Valid,Invalid,Missing}
#[derive(Debug,Clone,Copy,PartialEq,Eq)] pub enum TimebaseStatus{Trusted,Untrusted,Discontinuous}
#[derive(Debug,Clone,Copy,PartialEq,Eq)] pub enum ProtectionPermissive{NotRequired,IndependentlyPermitted,Blocked,Unknown}
#[derive(Debug,Clone,Copy,PartialEq,Eq)] pub enum PhysicalEffect{NotObserved,IndependentlyConfirmed,TelemetryOnly,Spoofed,Stale,OutOfOrder}
#[derive(Debug,Clone,Copy,PartialEq,Eq)] pub enum ObservationSource{IndependentPhysicalFeedback,SupervisoryTelemetry,DeviceAcknowledgement,Unknown}
#[derive(Debug,Clone,Copy,PartialEq,Eq)] pub enum AdmissionDecision{Rejected,Admitted}
#[derive(Debug,Clone,Copy,PartialEq,Eq)] pub enum EffectDecision{PendingReconciliation,IndependentlyConfirmed}
#[derive(Debug,Clone,Copy,PartialEq,Eq)] pub enum RejectionReason{EmptyIdentity,IssuerUnknown,IssuerRevoked,IssuerExpired,SignatureInvalid,SignatureMissing,RoleNotAuthorized,KeyNotAuthorized,AssetNotAuthorized,CommandNotAuthorized,TransitionNotAuthorized,SupervisorySwitchgearProhibited,CommandIdReplayed,NonceReused,SequenceNotMonotonic,CommandNotYetValid,CommandExpired,TimebaseUntrusted,PreStateMismatch,PreStateEpochMismatch,PreStateDigestMismatch,TopologyConfigurationMismatch,ControllerConfigurationMismatch,ProtectionConfigurationMismatch,PayloadDigestInvalid,EnvelopeDigestInvalid,LeaderEpochMismatch,SplitBrainDetected,ProtectionPermissiveMissing,ProtectionResetNotAuthorized,ProtectionResetEvidenceMissing}
#[derive(Debug,Clone,PartialEq,Eq)] pub struct CommandIntent{pub command_id:String,pub issuer_id:String,pub issuer_role:String,pub key_id:String,pub identity_status:IdentityStatus,pub signature_status:SignatureStatus,pub asset_id:String,pub command_type:String,pub transition_id:String,pub nonce:String,pub sequence:u64,pub issued_at_ms:u64,pub expires_at_ms:u64,pub timebase_status:TimebaseStatus,pub expected_pre_state_id:String,pub expected_pre_state_epoch:u64,pub pre_state_sha256:String,pub topology_sha256:String,pub controller_configuration_sha256:String,pub protection_configuration_sha256:String,pub payload_sha256:String,pub envelope_sha256:String,pub leader_epoch:u64}
#[derive(Debug,Clone,PartialEq,Eq)] pub struct AdmissionPolicy{pub asset_id:String,pub authorized_issuer_roles:Vec<String>,pub authorized_key_ids:Vec<String>,pub authorized_asset_ids:Vec<String>,pub authorized_command_types:Vec<String>,pub authorized_transition_ids:Vec<String>,pub current_state_id:String,pub current_state_epoch:u64,pub current_pre_state_sha256:String,pub topology_sha256:String,pub controller_configuration_sha256:String,pub protection_configuration_sha256:String,pub current_time_ms:u64,pub trusted_timebase_status:TimebaseStatus,pub last_accepted_sequence:u64,pub consumed_command_ids:Vec<String>,pub consumed_nonces:Vec<String>,pub leader_epoch:u64,pub active_controller_count:u32,pub protection_interlock_required:bool,pub protection_permissive:ProtectionPermissive,pub maintenance_clearance_receipt_current:bool,pub physical_cause_cleared:bool,pub independent_trip_clear_verified:bool,pub expected_post_state_id:String,pub expected_post_state_epoch:u64,pub max_observation_age_ms:u64}
#[derive(Debug,Clone,PartialEq,Eq)] pub struct AdmissionAssessment{pub decision:AdmissionDecision,pub reasons:Vec<RejectionReason>,pub dispatch_permission:bool,pub state_promotion_permission:bool,pub claim_ceiling:&'static str}
#[derive(Debug,Clone,PartialEq,Eq)] pub struct EffectObservation{pub command_id:String,pub physical_effect:PhysicalEffect,pub source:ObservationSource,pub source_identity_status:IdentityStatus,pub timebase_status:TimebaseStatus,pub observed_at_ms:u64,pub observed_sequence:u64,pub observed_state_id:String,pub observed_state_epoch:u64,pub observation_sha256:String}
#[derive(Debug,Clone,PartialEq,Eq)] pub struct EffectAssessment{pub decision:EffectDecision,pub promotion_permission:bool,pub reconcile_before_next_mutation:bool,pub warnings:Vec<RejectionReason>,pub claim_ceiling:&'static str}
fn nonblank(x:&str)->bool{!x.trim().is_empty()} fn digest(x:&str)->bool{x.len()==64&&x.bytes().all(|b|b.is_ascii_hexdigit())}
fn has(xs:&[String],x:&str)->bool{xs.iter().any(|v|v==x)} fn switchgear(x:&str)->bool{matches!(x,"OPEN_PCC"|"CLOSE_PCC"|"RESET_PROTECTION"|"BYPASS_INTERLOCK")}
pub fn assess_admission(i:&CommandIntent,p:&AdmissionPolicy)->AdmissionAssessment{
 let mut r=Vec::new();
 if [i.command_id.as_str(),i.issuer_id.as_str(),i.issuer_role.as_str(),i.key_id.as_str(),i.asset_id.as_str(),i.command_type.as_str(),i.transition_id.as_str(),i.nonce.as_str(),i.expected_pre_state_id.as_str()].iter().any(|x|!nonblank(x)){r.push(RejectionReason::EmptyIdentity);}
 match i.identity_status{IdentityStatus::Current=>(),IdentityStatus::Unknown=>r.push(RejectionReason::IssuerUnknown),IdentityStatus::Revoked=>r.push(RejectionReason::IssuerRevoked),IdentityStatus::Expired=>r.push(RejectionReason::IssuerExpired)}
 match i.signature_status{SignatureStatus::Valid=>(),SignatureStatus::Invalid=>r.push(RejectionReason::SignatureInvalid),SignatureStatus::Missing=>r.push(RejectionReason::SignatureMissing)}
 if !has(&p.authorized_issuer_roles,&i.issuer_role){r.push(RejectionReason::RoleNotAuthorized)} if !has(&p.authorized_key_ids,&i.key_id){r.push(RejectionReason::KeyNotAuthorized)}
 if i.asset_id!=p.asset_id||!has(&p.authorized_asset_ids,&i.asset_id){r.push(RejectionReason::AssetNotAuthorized)}
 if !has(&p.authorized_command_types,&i.command_type){r.push(RejectionReason::CommandNotAuthorized)} if !has(&p.authorized_transition_ids,&i.transition_id){r.push(RejectionReason::TransitionNotAuthorized)}
 if i.issuer_role=="supervisory_mems"&&switchgear(&i.command_type){r.push(RejectionReason::SupervisorySwitchgearProhibited)}
 if has(&p.consumed_command_ids,&i.command_id){r.push(RejectionReason::CommandIdReplayed)} if has(&p.consumed_nonces,&i.nonce){r.push(RejectionReason::NonceReused)}
 if i.sequence<=p.last_accepted_sequence{r.push(RejectionReason::SequenceNotMonotonic)} if i.issued_at_ms>p.current_time_ms{r.push(RejectionReason::CommandNotYetValid)}
 if i.expires_at_ms<p.current_time_ms||i.expires_at_ms<i.issued_at_ms{r.push(RejectionReason::CommandExpired)}
 if i.timebase_status!=TimebaseStatus::Trusted||p.trusted_timebase_status!=TimebaseStatus::Trusted{r.push(RejectionReason::TimebaseUntrusted)}
 if i.expected_pre_state_id!=p.current_state_id{r.push(RejectionReason::PreStateMismatch)} if i.expected_pre_state_epoch!=p.current_state_epoch{r.push(RejectionReason::PreStateEpochMismatch)}
 if i.pre_state_sha256!=p.current_pre_state_sha256||!digest(&i.pre_state_sha256){r.push(RejectionReason::PreStateDigestMismatch)}
 if i.topology_sha256!=p.topology_sha256||!digest(&i.topology_sha256){r.push(RejectionReason::TopologyConfigurationMismatch)}
 if i.controller_configuration_sha256!=p.controller_configuration_sha256||!digest(&i.controller_configuration_sha256){r.push(RejectionReason::ControllerConfigurationMismatch)}
 if i.protection_configuration_sha256!=p.protection_configuration_sha256||!digest(&i.protection_configuration_sha256){r.push(RejectionReason::ProtectionConfigurationMismatch)}
 if !digest(&i.payload_sha256){r.push(RejectionReason::PayloadDigestInvalid)} if !digest(&i.envelope_sha256){r.push(RejectionReason::EnvelopeDigestInvalid)}
 if i.leader_epoch!=p.leader_epoch{r.push(RejectionReason::LeaderEpochMismatch)} if p.active_controller_count!=1{r.push(RejectionReason::SplitBrainDetected)}
 if p.protection_interlock_required&&p.protection_permissive!=ProtectionPermissive::IndependentlyPermitted{r.push(RejectionReason::ProtectionPermissiveMissing)}
 if i.command_type=="RESET_PROTECTION"{if i.issuer_role!="qualified_operator"||!has(&p.authorized_issuer_roles,"qualified_operator"){r.push(RejectionReason::ProtectionResetNotAuthorized)} if !p.maintenance_clearance_receipt_current||!p.physical_cause_cleared||!p.independent_trip_clear_verified{r.push(RejectionReason::ProtectionResetEvidenceMissing)}}
 let ok=r.is_empty(); AdmissionAssessment{decision:if ok{AdmissionDecision::Admitted}else{AdmissionDecision::Rejected},reasons:r,dispatch_permission:ok,state_promotion_permission:false,claim_ceiling:CLAIM}
}
/// Call after dispatch or when its outcome is ambiguous. Missing observation means unknown, not safe to retry.
pub fn assess_effect(i:&CommandIntent,p:&AdmissionPolicy,o:Option<&EffectObservation>)->EffectAssessment{
 let Some(o)=o else{return EffectAssessment{decision:EffectDecision::PendingReconciliation,promotion_permission:false,reconcile_before_next_mutation:true,warnings:vec![],claim_ceiling:CLAIM};};
 let fresh=o.observed_at_ms<=p.current_time_ms&&p.current_time_ms.saturating_sub(o.observed_at_ms)<=p.max_observation_age_ms;
 let ok=o.command_id==i.command_id&&o.observed_sequence==i.sequence&&o.physical_effect==PhysicalEffect::IndependentlyConfirmed&&o.source==ObservationSource::IndependentPhysicalFeedback&&o.source_identity_status==IdentityStatus::Current&&o.timebase_status==TimebaseStatus::Trusted&&fresh&&o.observed_at_ms>=i.issued_at_ms&&o.observed_state_id==p.expected_post_state_id&&o.observed_state_epoch==p.expected_post_state_epoch&&digest(&o.observation_sha256);
 if ok{return EffectAssessment{decision:EffectDecision::IndependentlyConfirmed,promotion_permission:true,reconcile_before_next_mutation:false,warnings:vec![],claim_ceiling:CLAIM};}
 let mut w=Vec::new();if o.command_id!=i.command_id||o.observed_sequence!=i.sequence||o.physical_effect==PhysicalEffect::OutOfOrder{w.push(RejectionReason::SequenceNotMonotonic)}
 if o.physical_effect==PhysicalEffect::Spoofed||o.source_identity_status!=IdentityStatus::Current{w.push(RejectionReason::IssuerUnknown)}
 if o.source!=ObservationSource::IndependentPhysicalFeedback||o.physical_effect==PhysicalEffect::TelemetryOnly||o.physical_effect==PhysicalEffect::NotObserved{w.push(RejectionReason::SignatureMissing)}
 if o.physical_effect==PhysicalEffect::Stale||o.timebase_status!=TimebaseStatus::Trusted||!fresh{w.push(RejectionReason::TimebaseUntrusted)}
 if o.observed_state_id!=p.expected_post_state_id||o.observed_state_epoch!=p.expected_post_state_epoch||!digest(&o.observation_sha256){w.push(RejectionReason::PreStateMismatch)}
 EffectAssessment{decision:EffectDecision::PendingReconciliation,promotion_permission:false,reconcile_before_next_mutation:true,warnings:w,claim_ceiling:CLAIM}
}
#[cfg(test)] mod tests{
 use super::*;fn h(c:char)->String{std::iter::repeat(c).take(64).collect()}
 fn i()->CommandIntent{CommandIntent{command_id:"cmd-42".into(),issuer_id:"issuer".into(),issuer_role:"local_controller".into(),key_id:"key".into(),identity_status:IdentityStatus::Current,signature_status:SignatureStatus::Valid,asset_id:"asset".into(),command_type:"OPEN_PCC".into(),transition_id:"T02".into(),nonce:"nonce-42".into(),sequence:42,issued_at_ms:1000,expires_at_ms:2000,timebase_status:TimebaseStatus::Trusted,expected_pre_state_id:"island_preparation".into(),expected_pre_state_epoch:7,pre_state_sha256:h('1'),topology_sha256:h('2'),controller_configuration_sha256:h('3'),protection_configuration_sha256:h('4'),payload_sha256:h('5'),envelope_sha256:h('6'),leader_epoch:9}}
 fn p()->AdmissionPolicy{AdmissionPolicy{asset_id:"asset".into(),authorized_issuer_roles:vec!["local_controller".into(),"qualified_operator".into()],authorized_key_ids:vec!["key".into()],authorized_asset_ids:vec!["asset".into()],authorized_command_types:vec!["OPEN_PCC".into(),"CLOSE_PCC".into(),"RESET_PROTECTION".into()],authorized_transition_ids:vec!["T02".into()],current_state_id:"island_preparation".into(),current_state_epoch:7,current_pre_state_sha256:h('1'),topology_sha256:h('2'),controller_configuration_sha256:h('3'),protection_configuration_sha256:h('4'),current_time_ms:1500,trusted_timebase_status:TimebaseStatus::Trusted,last_accepted_sequence:41,consumed_command_ids:vec!["cmd-10".into()],consumed_nonces:vec!["nonce-10".into()],leader_epoch:9,active_controller_count:1,protection_interlock_required:true,protection_permissive:ProtectionPermissive::IndependentlyPermitted,maintenance_clearance_receipt_current:false,physical_cause_cleared:false,independent_trip_clear_verified:false,expected_post_state_id:"islanded".into(),expected_post_state_epoch:8,max_observation_age_ms:500}}
 fn obs(s:PhysicalEffect,src:ObservationSource)->EffectObservation{EffectObservation{command_id:"cmd-42".into(),physical_effect:s,source:src,source_identity_status:IdentityStatus::Current,timebase_status:TimebaseStatus::Trusted,observed_at_ms:1450,observed_sequence:42,observed_state_id:"islanded".into(),observed_state_epoch:8,observation_sha256:h('7')}}
 fn rejected(i:&CommandIntent,p:&AdmissionPolicy)->bool{assess_admission(i,p).decision==AdmissionDecision::Rejected}
 #[test]fn baseline_admits_but_never_promotes(){let a=assess_admission(&i(),&p());assert_eq!(a.decision,AdmissionDecision::Admitted);assert!(a.dispatch_permission);assert!(!a.state_promotion_permission);}
 #[test]fn identity_and_signature_states_fail_closed(){let mut x=i();x.identity_status=IdentityStatus::Revoked;assert!(rejected(&x,&p()));x=i();x.signature_status=SignatureStatus::Invalid;assert!(rejected(&x,&p()));}
 #[test]fn role_key_asset_command_transition_scopes_fail_closed(){let mut x=i();x.issuer_role="operator".into();assert!(rejected(&x,&p()));x=i();x.key_id="bad".into();assert!(rejected(&x,&p()));x=i();x.asset_id="bad".into();assert!(rejected(&x,&p()));x=i();x.command_type="BAD".into();assert!(rejected(&x,&p()));x=i();x.transition_id="BAD".into();assert!(rejected(&x,&p()));}
 #[test]fn mems_cannot_request_switchgear(){let mut x=i();x.issuer_role="supervisory_mems".into();assert!(rejected(&x,&p()));}
 #[test]fn command_nonce_sequence_and_expiry_replay_fail_closed(){let mut x=i();x.command_id="cmd-10".into();assert!(rejected(&x,&p()));x=i();x.nonce="nonce-10".into();assert!(rejected(&x,&p()));x=i();x.sequence=41;assert!(rejected(&x,&p()));x=i();x.expires_at_ms=1000;assert!(rejected(&x,&p()));}
 #[test]fn state_and_configuration_epoch_drift_fail_closed(){let mut x=i();x.expected_pre_state_epoch=6;assert!(rejected(&x,&p()));x=i();x.expected_pre_state_id="grid_connected".into();assert!(rejected(&x,&p()));x=i();x.topology_sha256=h('8');assert!(rejected(&x,&p()));}
 #[test]fn leadership_and_protection_permissive_are_required(){let mut pol=p();pol.active_controller_count=2;assert!(rejected(&i(),&pol));pol=p();pol.protection_permissive=ProtectionPermissive::Unknown;assert!(rejected(&i(),&pol));}
 #[test]fn protection_reset_requires_qualified_operator_and_clearance(){let mut x=i();x.command_type="RESET_PROTECTION".into();x.issuer_role="qualified_operator".into();assert!(rejected(&x,&p()));}
 #[test]fn missing_effect_requires_reconciliation(){let e=assess_effect(&i(),&p(),None);assert!(!e.promotion_permission);assert!(e.reconcile_before_next_mutation);}
 #[test]fn acknowledgement_or_telemetry_is_not_physical_effect(){for(src,eff)in[(ObservationSource::DeviceAcknowledgement,PhysicalEffect::NotObserved),(ObservationSource::SupervisoryTelemetry,PhysicalEffect::TelemetryOnly)]{let e=assess_effect(&i(),&p(),Some(&obs(eff,src)));assert!(!e.promotion_permission);assert!(e.reconcile_before_next_mutation);}}
 #[test]fn spoofed_stale_and_out_of_order_feedback_never_promotes(){for x in[PhysicalEffect::Spoofed,PhysicalEffect::Stale,PhysicalEffect::OutOfOrder]{let e=assess_effect(&i(),&p(),Some(&obs(x,ObservationSource::IndependentPhysicalFeedback)));assert!(!e.promotion_permission);}}
 #[test]fn matching_fresh_independent_feedback_promotes(){let e=assess_effect(&i(),&p(),Some(&obs(PhysicalEffect::IndependentlyConfirmed,ObservationSource::IndependentPhysicalFeedback)));assert_eq!(e.decision,EffectDecision::IndependentlyConfirmed);assert!(e.promotion_permission);}
 #[test]fn wrong_command_sequence_or_state_never_promotes(){let mut x=obs(PhysicalEffect::IndependentlyConfirmed,ObservationSource::IndependentPhysicalFeedback);x.command_id="wrong".into();assert!(!assess_effect(&i(),&p(),Some(&x)).promotion_permission);x=obs(PhysicalEffect::IndependentlyConfirmed,ObservationSource::IndependentPhysicalFeedback);x.observed_state_id="unknown_hold".into();assert!(!assess_effect(&i(),&p(),Some(&x)).promotion_permission);}
 #[test]fn untrusted_observer_clock_or_digest_never_promotes(){let mut x=obs(PhysicalEffect::IndependentlyConfirmed,ObservationSource::IndependentPhysicalFeedback);x.source_identity_status=IdentityStatus::Unknown;assert!(!assess_effect(&i(),&p(),Some(&x)).promotion_permission);x=obs(PhysicalEffect::IndependentlyConfirmed,ObservationSource::IndependentPhysicalFeedback);x.timebase_status=TimebaseStatus::Untrusted;assert!(!assess_effect(&i(),&p(),Some(&x)).promotion_permission);x=obs(PhysicalEffect::IndependentlyConfirmed,ObservationSource::IndependentPhysicalFeedback);x.observation_sha256="bad".into();assert!(!assess_effect(&i(),&p(),Some(&x)).promotion_permission);}
 #[test]fn claim_ceiling_excludes_real_crypto_verification(){assert!(CLAIM.contains("NOT_SIGNATURE_VERIFICATION"));assert_eq!(assess_admission(&i(),&p()).claim_ceiling,CLAIM);}
}
